const data = $json;

// ==================================================
// GET IDS FROM WEBHOOK
// ==================================================

const webhook = $('Webhook').first().json;

const conversationId = webhook.body.conversation_id;
const messageId = webhook.body.message_id;

if (!conversationId) {
  throw new Error("Missing conversation_id.");
}

if (!messageId) {
  throw new Error("Missing message_id.");
}


// ==================================================
// URGENCY SCORE MAPPING
// ==================================================

const impactScores = {
  "No impact / informational": 0,
  "Minor inconvenience": 10,
  "Significant inconvenience": 20,
  "Severe impact": 30
};

const timeScores = {
  "No time pressure": 0,
  "Can wait / flexible": 10,
  "Needs attention soon": 20,
  "Immediate / deadline": 30
};

const blockingScores = {
  "Not blocked": 0,
  "Slightly inconvenienced": 5,
  "Important action affected": 15,
  "Completely blocked": 25
};

const persistenceScores = {
  "New / first contact": 0,
  "Recent": 5,
  "Delayed / unresolved": 10,
  "Long-standing / repeated attempts": 15
};

const signals = data.urgency_signals;

const urgencyScore =
  (impactScores[signals.impact] ?? 0) +
  (timeScores[signals.time_sensitivity] ?? 0) +
  (blockingScores[signals.blocking] ?? 0) +
  (persistenceScores[signals.persistence] ?? 0);


// ==================================================
// RETURN FINAL DATA
// ==================================================

return [
  {
    json: {
      conversation_id: conversationId,
      message_id: messageId,

      language: data.language,
      intent: data.intent,
      sentiment: data.sentiment,
      order_reference: data.order_reference ?? null,

      urgency_score: urgencyScore,
      urgency_signals: data.urgency_signals,

      queue: data.queue
    }
  }
];

const webhook = $('Webhook').first().json;

const conversationId = webhook.body.conversation_id;
const customerId = webhook.body.customer_id;
const messageId = webhook.body.message_id;

if (!conversationId || !customerId || !messageId) {
  throw new Error(
    `Missing IDs. Received: conversation_id=${conversationId}, customer_id=${customerId}, message_id=${messageId}`
  );
}

const supabaseUrl = 'https://jikdykibhyewrfnlpptv.supabase.co';
const supabaseKey = 'sb_secret_1g3-NRYivFEIBV415V3tnw_GcnjqMkI';

const headers = {
  apikey: supabaseKey,
  Authorization: `Bearer ${supabaseKey}`,
  'Content-Type': 'application/json'
};

async function supabaseGet(table, query) {
  return await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/${table}?${query}`,
    headers
  });
}

// 1. Get conversation
const conversation = await supabaseGet(
  'conversations',
  `select=id,customer_id,order_id,channel,status,queue,language,intent,sentiment,urgency_score,priority,created_at,updated_at&id=eq.${conversationId}`
);

// 2. Get conversation history
const history = await supabaseGet(
  'messages',
  `select=id,sender_type,sender_id,content,created_at&conversation_id=eq.${conversationId}&order=created_at.asc&limit=20`
);

// 3. Get customer
const customer = await supabaseGet(
  'customers',
  `select=id,full_name,email,phone&id=eq.${customerId}`
);

// 4. Get customer orders
const orders = await supabaseGet(
  'orders',
  `select=id,customer_id,order_number,status,total_amount,currency,ordered_at,expected_delivery_at,delivered_at,tracking_number&customer_id=eq.${customerId}&order=ordered_at.desc`
);

// 5. Build complete context
return [
  {
