      orders: orders
    }
  }
];

const raw = $json.text;

if (!raw) {
  throw new Error("LLM returned an empty response.");
}

let cleaned = String(raw).trim();

cleaned = cleaned
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let data;

try {
  data = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `Invalid JSON from LLM: ${error.message}\n\nRaw output:\n${raw}`
  );
}

if (!data.language) {
  throw new Error("Missing field: language");
}

if (!data.intent) {
  throw new Error("Missing field: intent");
}

if (!data.queue) {
  throw new Error("Missing field: queue");
}

if (!data.sentiment) {
  throw new Error("Missing field: sentiment");
}

if (!data.urgency_signals) {
  throw new Error("Missing field: urgency_signals");
}

const allowedQueues = [
  "delivery",
  "returns",
  "payment",
  "products",
  "general"
];

if (!allowedQueues.includes(data.queue)) {
  throw new Error(`Invalid queue: ${data.queue}`);
}

return [
  {
    json: data
  }
];
